const crypto = require('crypto');

// Validação opcional de segredo de webhook (se configurado nas variáveis de ambiente)
const vindoDeWebhook = $json.headers !== undefined;
const secretEsperado = $env.WEBHOOK_SHARED_SECRET;
if (vindoDeWebhook && secretEsperado) {
  const secretRecebido = $json.headers['x-webhook-secret'];
  if (secretRecebido !== secretEsperado) {
    throw new Error('Webhook não autorizado: header x-webhook-secret ausente ou incorreto.');
  }
}

const body = $json.body || $json || {};

// Mapeamento de URL e extração do product_id
const rawUrl = (body.raw_product_url || body.url_produto || body.url || '').toString().trim();
const productId = (body.product_id || '').toString().trim() || crypto.randomUUID();

// Detecção automática de origem se vier vazia ou desconhecida
let origem = (body.origem || '').toString().toLowerCase().trim();
if (!origem && rawUrl) {
  if (rawUrl.includes('shopee.')) origem = 'shopee';
  else if (rawUrl.includes('aliexpress.')) origem = 'aliexpress';
  else if (rawUrl.includes('mercadolivre.') || rawUrl.includes('mercadolibre.')) origem = 'mercado_livre';
}
if (origem === 'mercadolivre') origem = 'mercado_livre';

// Extração de preço numérico
const precoBruto = body?.price?.promotional ?? body?.price?.original ?? body?.preco ?? body?.price ?? 0;
const precoNum = Number(precoBruto) || 0;

return [{
  json: {
    product_id: productId,
    origem: origem,
    raw_product_url: rawUrl,
    title: body.title || body.titulo || body.nome || 'Produto Minerado',
    category: body.category || body.categoria || 'Geral',
    price: {
      original: Number(body?.price?.original ?? precoNum),
      promotional: precoNum,
      currency: body?.price?.currency || 'BRL'
    },
    media: {
      raw_images: Array.isArray(body?.media?.raw_images) ? body.media.raw_images : (Array.isArray(body?.raw_images) ? body.raw_images : (body?.raw_images ? [body.raw_images] : [])),
      raw_videos: Array.isArray(body?.media?.raw_videos) ? body.media.raw_videos : (Array.isArray(body?.raw_videos) ? body.raw_videos : (body?.raw_videos ? [body.raw_videos] : []))
    }
  }
}];
